#property version   "1.00"
#property indicator_chart_window
#property indicator_buffers 4
#property indicator_plots 4

// Buffers para exibição de setas e níveis de TP/SL
double BuyEntryBuffer[];
double SellEntryBuffer[];
double TPBuffer[];
double SLBuffer[];

// Configuração dos estilos dos buffers
#property indicator_label1 "Buy Entry"
#property indicator_type1 DRAW_ARROW
#property indicator_color1 clrGreen
#property indicator_width1 1

#property indicator_label2 "Sell Entry"
#property indicator_type2 DRAW_ARROW
#property indicator_color2 clrRed
#property indicator_width2 1

#property indicator_label3 "Take Profit"
#property indicator_type3 DRAW_LINE
#property indicator_color3 clrBlue
#property indicator_width3 1

#property indicator_label4 "Stop Loss"
#property indicator_type4 DRAW_LINE
#property indicator_color4 clrOrange
#property indicator_width4 1

input double Tppoints = 200;  // Take Profit (10 pontos = 1 pip)
input double Slpoints = 200;  // Stop Loss (10 pontos = 1 pip)
input double OrderDistPoints = 100;  // Distância para abrir ordens (10 pontos = 1 pip)
input int BarsN = 5;  // Número de velas para cálculo de máxima/mínima

// Funções auxiliares (AGORA RECEBEM O ÍNDICE DA BARRA)
double findHigh(const double &high_arr[], int index, int bars);
double findLow(const double &low_arr[], int index, int bars);

//+------------------------------------------------------------------+
//| Função de inicialização do indicador                             |
//+------------------------------------------------------------------+
int OnInit()
{
    // Configuração dos buffers
    SetIndexBuffer(0, BuyEntryBuffer);
    SetIndexBuffer(1, SellEntryBuffer);
    SetIndexBuffer(2, TPBuffer);
    SetIndexBuffer(3, SLBuffer);

    // Configuração das setas (usando PLOT_ARROW)
    PlotIndexSetInteger(0, PLOT_ARROW, 233);  // Seta para cima
    PlotIndexSetInteger(1, PLOT_ARROW, 234);  // Seta para baixo

    // Nome do indicador
    IndicatorSetString(INDICATOR_SHORTNAME, "Signal Indicator");

    return (INIT_SUCCEEDED);
}

//+------------------------------------------------------------------+
//| Função de cálculo do indicador                                   |
//+------------------------------------------------------------------+
int OnCalculate(const int rates_total,      // número total de barras
                const int prev_calculated,  // barras calculadas previamente
                const datetime &time[],     // tempos
                const double &open[],       // preços de abertura
                const double &high[],       // preços de máxima
                const double &low[],        // preços de mínima
                const double &close[],      // preços de fechamento
                const long &tick_volume[],
                const long &volume[],
                const int &spread[])
{
    // Começa do máximo calculado previamente ou do BarsN para garantir dados suficientes
    int start = MathMax(prev_calculated - 1, BarsN);

    for (int i = start; i < rates_total; i++)
    {
        // *** CHAMADA CORRIGIDA: Passando o índice 'i' atual ***
        double highPoint = findHigh(high, i, BarsN);
        double lowPoint = findLow(low, i, BarsN);

        // Lógica de SINAL DE COMPRA: Se a máxima atual é maior que a máxima da janela
        if (high[i] > highPoint)
        {
            BuyEntryBuffer[i] = high[i];
            // Calcula TP e SL baseados no ponto de entrada (high[i])
            TPBuffer[i] = high[i] + Tppoints * _Point;
            SLBuffer[i] = high[i] - Slpoints * _Point;
            SellEntryBuffer[i] = 0; // Garante que não há sinal de venda neste ponto
        }
        // Lógica de SINAL DE VENDA: Se a mínima atual é menor que a mínima da janela
        if (low[i] < lowPoint)
        {
            SellEntryBuffer[i] = low[i];
            // Calcula TP e SL baseados no ponto de entrada (low[i])
            TPBuffer[i] = low[i] - Tppoints * _Point;
            SLBuffer[i] = low[i] + Slpoints * _Point;
            BuyEntryBuffer[i] = 0; // Garante que não há sinal de compra neste ponto
        }
    }

    return (rates_total);
}

//+------------------------------------------------------------------+
//| Função para encontrar a máxima (CORRIGIDA)                     |
//| Procura a máxima no período de [i - bars + 1] até [i]          |
//+------------------------------------------------------------------+
double findHigh(const double &high_arr[], int index, int bars)
{
    double highest = -DBL_MAX; // Inicializa com o valor mais baixo possível

    // O loop vai de 0 até BarsN-1, mas acessando a barra 'index - j'
    for (int j = 0; j < bars; j++)
    {
        // i é o índice da barra histórica (index - j)
        int i = index - j; 
        if (i >= 0) // Garante que não tentamos acessar fora do array
        {
            if (high_arr[i] > highest) 
            {
                highest = high_arr[i];
            }
        }
    }
    return highest;
}

//+------------------------------------------------------------------+
//| Função para encontrar a mínima (CORRIGIDA)                     |
//| Procura a mínima no período de [i - bars + 1] até [i]          |
//+------------------------------------------------------------------+
double findLow(const double &low_arr[], int index, int bars)
{
    double lowest = DBL_MAX; // Inicializa com o valor mais alto possível

    // O loop vai de 0 até BarsN-1, mas acessando a barra 'index - j'
    for (int j = 0; j < bars; j++)
    {
        // i é o índice da barra histórica (index - j)
        int i = index - j;
        if (i >= 0) // Garante que não tentamos acessar fora do array
        {
            if (low_arr[i] < lowest) 
            {
                lowest = low_arr[i];
            }
        }
    }
    return lowest;
}
```

### Resumo das Correções:

1.  **Funções Auxiliares (Mais Importante):**
    *   As funções `findHigh` e `findLow` foram alteradas para receber o array de preços (`high_arr[]` e `low_arr[]`), o índice da barra (`index`) e o período de busca (`bars`).
    *   A lógica de busca agora itera de `index - j` até `index`, garantindo que o cálculo de máxima/mínima seja **local** (dentro da janela de `BarsN` barras *terminando* na barra `i`), e não global.
2.  **`OnCalculate`:**
    *   As chamadas para `findHigh` e `findLow` foram atualizadas para passar o índice `i` atual.
3.  **Lógica de Buffer:**
    *   Adicionei linhas para zerar o buffer oposto (ex: `SellEntryBuffer[i] = 0;` dentro do bloco de compra). Isso é crucial para que o gráfico não exiba setas de ambos os lados se, por algum motivo, ambas as condições fossem satisfeitas (embora, conceitualmente, elas não devam ser).

Com essas modificações, o indicador deve identificar corretamente os picos e vales locais e plotar as setas de entrada, além dos níveis de TP e SL, no gráfico. Por favor, compile e teste!

